-- The PHP contact form only saved messages if this table existed, and it never did. Not part of the dump,
-- so re-run this after a fresh `load-db --force`; load-db doesn't drop it.
CREATE TABLE IF NOT EXISTS "contact_messages" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "email" varchar(150) NOT NULL,
  "phone" varchar(30) DEFAULT NULL,
  "subject" varchar(100) DEFAULT NULL,
  "message" text NOT NULL,
  "ip_address" varchar(45) DEFAULT NULL,
  "user_agent" varchar(500) DEFAULT NULL,
  "is_read" smallint DEFAULT 0,
  "created_at" timestamp DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "contact_messages_idx_created" ON "contact_messages" ("created_at");
CREATE INDEX IF NOT EXISTS "contact_messages_idx_ip" ON "contact_messages" ("ip_address");
